import fs from 'node:fs';
import path from 'node:path';
import type { ComplianceCountry } from './types';

/**
 * Globe geometry is generated by `scripts/build-world-map.mjs`
 * from Natural Earth (public domain) via world-atlas (© Mike Bostock, BSD-3-Clause).
 */
interface WorldCountry {
  id: string;
  lon: number;
  lat: number;
  small: boolean;
}

interface WorldFile {
  notice: string;
  countries: WorldCountry[];
}

const world = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), 'src/data/world-polygons.json'), 'utf8'),
) as WorldFile;

/** Site codes that are not already ISO 3166-1 alpha-2. */
const ISO_ALIAS: Record<string, string> = { uk: 'gb' };

/**
 * Drawn as the EU market only when that member has no compliance file of its own.
 * UK is a separate page.
 */
const EU_MEMBER_ISO = [
  'at', 'be', 'bg', 'hr', 'cy', 'cz', 'dk', 'ee', 'fi', 'fr', 'de', 'gr',
  'hu', 'ie', 'it', 'lv', 'lt', 'lu', 'mt', 'nl', 'pl', 'pt', 'ro', 'sk',
  'si', 'es', 'se',
] as const;

export interface ComplianceMapLink {
  cc: string;
  name: string;
  region: string;
  must: number;
  /** ISO codes painted for this market. Several when a page covers more than one country. */
  isos: string[];
  lat: number;
  lon: number;
  small: boolean;
}

export interface ComplianceMapRegion {
  id: string;
  lat: number;
  lon: number;
}

export interface ComplianceMapOff {
  cc: string;
  name: string;
  region: string;
  must: number;
}

export interface ComplianceMapModel {
  links: ComplianceMapLink[];
  offMap: ComplianceMapOff[];
  regions: ComplianceMapRegion[];
  note: string;
}

function isoForSite(cc: string): string {
  const key = cc.toLowerCase();
  return ISO_ALIAS[key] ?? key;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

function meanLonLat(points: { lat: number; lon: number }[]): { lat: number; lon: number } {
  let x = 0;
  let y = 0;
  let z = 0;
  for (const point of points) {
    const lon = (point.lon * Math.PI) / 180;
    const lat = (point.lat * Math.PI) / 180;
    const cos = Math.cos(lat);
    x += cos * Math.cos(lon);
    y += cos * Math.sin(lon);
    z += Math.sin(lat);
  }
  const lon = (Math.atan2(y, x) * 180) / Math.PI;
  const lat = (Math.atan2(z, Math.hypot(x, y)) * 180) / Math.PI;
  return { lat: round2(lat), lon: round2(lon) };
}

function mustCount(country: ComplianceCountry): number {
  return country.items.filter((item) => item.mandatory).length;
}

export function buildComplianceMap(countries: ComplianceCountry[]): ComplianceMapModel {
  const byId = new Map<string, WorldCountry>();
  for (const shape of world.countries) {
    if (shape.id && !byId.has(shape.id)) byId.set(shape.id, shape);
  }

  const used = new Set<string>();
  const links: ComplianceMapLink[] = [];
  const regionPoints = new Map<string, { lat: number; lon: number }[]>();

  const addPoint = (region: string, lat: number, lon: number) => {
    const list = regionPoints.get(region) ?? [];
    list.push({ lat, lon });
    regionPoints.set(region, list);
  };

  for (const country of countries) {
    if (country.country === 'eu') continue;
    const iso = isoForSite(country.country);
    const shape = byId.get(iso);
    if (!shape) continue;
    used.add(iso);
    links.push({
      cc: country.country,
      name: country.name_zh,
      region: country.region,
      must: mustCount(country),
      isos: [iso],
      lat: shape.lat,
      lon: shape.lon,
      small: shape.small,
    });
    addPoint(country.region, shape.lat, shape.lon);
  }

  const eu = countries.find((country) => country.country === 'eu');
  if (eu) {
    const members = EU_MEMBER_ISO.filter((iso) => byId.has(iso) && !used.has(iso));
    const shapes = members.flatMap((iso) => {
      const shape = byId.get(iso);
      return shape ? [shape] : [];
    });
    if (shapes.length) {
      for (const iso of members) used.add(iso);
      const focus = meanLonLat(shapes.map((shape) => ({ lat: shape.lat, lon: shape.lon })));
      links.push({
        cc: eu.country,
        name: eu.name_zh,
        region: eu.region,
        must: mustCount(eu),
        isos: members.filter((iso) => byId.has(iso)),
        lat: focus.lat,
        lon: focus.lon,
        small: false,
      });
      addPoint(eu.region, focus.lat, focus.lon);
    }
  }

  const linked = new Set(links.map((link) => link.cc));
  const offMap: ComplianceMapOff[] = countries
    .filter((country) => !linked.has(country.country))
    .map((country) => ({
      cc: country.country,
      name: country.name_zh,
      region: country.region,
      must: mustCount(country),
    }));

  const regions: ComplianceMapRegion[] = [];
  for (const country of countries) {
    if (regions.some((region) => region.id === country.region)) continue;
    const points = regionPoints.get(country.region);
    if (!points?.length) continue;
    regions.push({ id: country.region, ...meanLonLat(points) });
  }

  const note = offMap.length
    ? `亮色国家可以点进合规页，暗色国家没有单独页面。地球会缓慢自转，可以拖动旋转。未画在球面上的市场：${offMap.map((market) => market.name).join('、')}。边界来自 Natural Earth。`
    : '亮色国家可以点进合规页，暗色国家没有单独页面。地球会缓慢自转，可以拖动旋转。边界来自 Natural Earth。';

  if (!links.length) throw new Error('合规地图没有可进入的市场');

  return { links, offMap, regions, note };
}
